from decimal import Decimal

from src.billing.tax import line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_returns_integer_cents():
    assert tax_for(1000, Decimal("0.0825")) == 82
    assert isinstance(tax_for(1000, Decimal("0.0825")), int)


def test_tax_for_rounds_half_even():
    assert tax_for(250, Decimal("0.01")) == 2  # 2.5 -> 2
    assert tax_for(350, Decimal("0.01")) == 4  # 3.5 -> 4


def test_tax_for_accepts_float_rate_without_binary_error():
    # 0.0825 as a float is slightly below 0.0825; tax must still be computed on the decimal value
    assert tax_for(200, 0.0825) == tax_for(200, Decimal("0.0825")) == 16  # 16.5 -> 16


def test_tax_for_zero():
    assert tax_for(0, Decimal("0.2")) == 0
EOF
